1	//! Module / import / callable handlers: `mod` (inline + out-of-line), `use`
2	//! (named/alias/group/glob), `extern crate`, and `function_item` (free fns +
3	//! associated-fn bodies). Type/macro definitions live in [`super::types`].
4	
5	use tree_sitter::Node;
6	
7	use crate::ast::ParsedFile;
8	use crate::name_resolution::binding_lookup::{BindingKind, LocalFact};
9	use crate::name_resolution::rust_policy::{NS_TYPE, NS_VALUE, VIS_PUB};
10	use crate::name_resolution::types::{BindTarget, ExternRef, FileId, ScopeId, ScopeKind, Target};
11	
12	use super::super::builder::{join, parent_dir, scope_target, Builder};
13	use super::super::scopes::{
14	    child_of_kind, name_text, parse_cfg_for_item, parse_use, parse_vis, pattern_idents, vis,
15	    UseItem,
16	};
17	use super::locals::{add_locals, walk_block_body};
18	use super::{
19	    full_file_span, full_scope_span, node_range, resolve_restrict, vis_extent_from, with_node, Ctx,
20	    NodeId,
21	};
