23	// ── modules ───────────────────────────────────────────────────────────────────
24	
25	pub(in crate::name_resolution::rust_populator::walk) fn walk_mod_item(
26	    b: &mut Builder<'_>,
27	    path: &str,
28	    nid: &NodeId,
29	    scope: ScopeId,
30	    ctx: &Ctx,
31	) {
32	    let (name, has_body, body_range, vis_kind, vin, cond, path_attr) =
33	        with_node(b, path, nid, |pf, n| {
34	            let name = name_text(pf, n).unwrap_or_default();
35	            let body = n.child_by_field_name("body");
36	            let (vk, vin) = parse_vis(pf, n);
37	            let cond = parse_cfg_for_item(pf, n);
38	            let path_attr = mod_path_attr(pf, n);
39	            (
40	                name,
41	                body.is_some(),
42	                body.map(|x| (x.start_byte(), x.end_byte())),
43	                vk,
44	                vin,
45	                cond,
46	                path_attr,
47	            )
48	        });
49	    if name.is_empty() {
50	        return;
51	    }
52	    let restrict = vin.and_then(|p| resolve_restrict(b, scope, &p));
53	    let v = vis(vis_kind, restrict);
54	
55	    if has_body {
56	        // Inline module: a Module scope spanning the body, parented lexically at
57	        // `scope`. Its child-search dir is `<ctx.dir>/<name>/` (or `#[path]`).
58	        let (lo, hi) = body_range.unwrap();
59	        let inline = b.add_scope(
60	            ScopeKind::Module,
61	            Some(scope),
62	            ctx.file,
63	            lo,
64	            hi,
65	            cond.clone(),
66	        );
67	        b.add_binding(
68	            scope,
69	            name.clone(),
70	            NS_TYPE,
71	            scope_target(inline),
72	            v,
73	            cond.clone(),
74	            vec![vis_extent_from(b, scope, ctx.file, lo)],
75	        );
76	        let child_dir = match &path_attr {
77	            Some(rel) => parent_dir(&join(&ctx.dir, rel)),
78	            None => join(&ctx.dir, &format!("{name}/")),
79	        };
80	        let body_nid = with_node(b, path, nid, |_pf, n| {
81	            n.child_by_field_name("body").map(NodeId::of)
82	        });
83	        if let Some(body_nid) = body_nid {
84	            let inner_ctx = Ctx {
85	                file: ctx.file,
86	                dir: child_dir,
87	                module: inline,
88	            };
89	            super::walk_items_in(b, path, &body_nid, inline, &inner_ctx);
90	        }
91	    } else {
92	        // Out-of-line `mod name;` → resolve to a file via the declaring-dir rule.
93	        let pairs = b.build_out_of_line_module(
94	            scope,
95	            ctx.file,
96	            &name,
97	            &ctx.dir,
98	            path_attr.as_deref(),
99	            v.clone(),
100	            cond.clone(),
101	        );
102	        for (mod_scope, _src) in pairs {
103	            b.add_binding(
104	                scope,
105	                name.clone(),
106	                NS_TYPE,
107	                scope_target(mod_scope),
108	                v.clone(),
109	                cond.clone(),
110	                vec![full_file_span(ctx.file)],
111	            );
112	        }
113	    }
114	}
115	
116	/// The `#[path = "..."]` attribute value on a mod, if present.
117	fn mod_path_attr(pf: &ParsedFile, mod_node: &Node) -> Option<String> {
118	    let mut prev = mod_node.prev_sibling();
119	    while let Some(sib) = prev {
120	        if sib.kind() != "attribute_item" {
121	            break;
122	        }
123	        if let Some(attr) = child_of_kind(&sib, "attribute") {
124	            let head = attr.named_child(0).map(|n| pf.node_text(&n)).unwrap_or("");
125	            if head == "path" {
126	                if let Some(v) = attr.child_by_field_name("value") {
127	                    return Some(pf.node_text(&v).trim_matches('"').to_string());
128	                }
129	            }
130	        }
131	        prev = sib.prev_sibling();
132	    }
133	    None
134	}
135	
136	/// `extern crate dep [as bar];` → a Type binding for `bar` (or `dep`) at the
137	/// crate root, targeting the named in-workspace crate's Root scope when known,
138	/// else an `External` reference (recall-safe: a known-external, files `[]`).
139	pub(in crate::name_resolution::rust_populator::walk) fn walk_extern_crate(
140	    b: &mut Builder<'_>,
141	    path: &str,
142	    nid: &NodeId,
143	    scope: ScopeId,
144	    ctx: &Ctx,
145	) {
146	    let (crate_name, alias) = with_node(b, path, nid, |pf, n| {
147	        let crate_name = n
148	            .child_by_field_name("name")
149	            .map(|x| pf.node_text(&x).to_string())
150	            .unwrap_or_default();
151	        let alias = n
152	            .child_by_field_name("alias")
153	            .map(|x| pf.node_text(&x).to_string());
154	        (crate_name, alias)
155	    });
156	    if crate_name.is_empty() {
157	        return;
158	    }
159	    let bound = alias.unwrap_or_else(|| crate_name.clone());
160	    let target = match b.crate_root_named(&crate_name) {
161	        Some(root) => scope_target(root),
162	        None => BindTarget::Resolved(Target::External(ExternRef { name: crate_name })),
163	    };
164	    b.add_binding(
165	        scope,
166	        bound,
167	        NS_TYPE,
168	        target,
169	        vis(VIS_PUB, None),
170	        None,
171	        vec![full_scope_span(b, scope, ctx.file)],
172	    );
173	}
174	
175	// ── use declarations ───────────────────────────────────────────────────────────
176	
177	pub(in crate::name_resolution::rust_populator::walk) fn walk_use(
178	    b: &mut Builder<'_>,
179	    path: &str,
180	    nid: &NodeId,
181	    scope: ScopeId,
182	    ctx: &Ctx,
183	) {
184	    let edition = b.config().edition;
185	    let (items, vis_kind, cond, decl_lo) = with_node(b, path, nid, |pf, n| {
186	        let items = parse_use(pf, n, edition);
187	        let (vk, _vin) = parse_vis(pf, n);
188	        let cond = parse_cfg_for_item(pf, n);
189	        (items, vk, cond, n.start_byte())
190	    });
191	    // `use` visibility: `pub use` is a re-export (Public); plain `use` is private.
192	    let v = vis(vis_kind, None);
193	    // Block-local `use` is visible from the use site to the END of the enclosing
194	    // scope; a module/item-level `use` is order-independent and whole-scope.
195	    let extent = match b.graph_scope(scope).map(|s| &s.kind) {
196	        Some(ScopeKind::Module | ScopeKind::Root | ScopeKind::Type) => {
197	            full_scope_span(b, scope, ctx.file)
198	        }
199	        Some(ScopeKind::Block | ScopeKind::Callable)
200	        | Some(ScopeKind::ExternPrelude | ScopeKind::TranslationUnit)
201	        | None => vis_extent_from(b, scope, ctx.file, decl_lo),
202	    };
203	    let glob_vis_range = match b.graph_scope(scope).map(|s| &s.kind) {
204	        Some(ScopeKind::Block | ScopeKind::Callable) => Some(extent.clone()),
205	        Some(ScopeKind::Module | ScopeKind::Root | ScopeKind::Type) => None,
206	        Some(ScopeKind::ExternPrelude | ScopeKind::TranslationUnit) | None => Some(extent.clone()),
207	    };
208	    let mut order = 0u32;
209	    for item in items {
210	        match item {
211	            UseItem::Named {
212	                name,
213	                path: p,
214	                anchor,
215	            } => {
216	                b.add_binding(
217	                    scope,
218	                    name.clone(),
219	                    NS_VALUE,
220	                    BindTarget::Pending(p.clone(), anchor),
221	                    v.clone(),
222	                    cond.clone(),
223	                    vec![extent.clone()],
224	                );
225	                // A `use` may bring the name in Type ns too (module/type imports,
226	                // `use a::{self}`); add a Type-ns Pending so those paths resolve.
227	                b.add_binding(
228	                    scope,
229	                    name,
230	                    NS_TYPE,
231	                    BindTarget::Pending(p, anchor),
232	                    v.clone(),
233	                    cond.clone(),
234	                    vec![extent.clone()],
235	                );
236	            }
237	            UseItem::Glob { path: p, anchor } => {
238	                // Deferred-glob poison edge (no member expansion in Phase 1).
239	                b.add_glob_edge(
240	                    scope,
241	                    BindTarget::Pending(p, anchor),
242	                    v.clone(),
243	                    cond.clone(),
244	                    order,
245	                    glob_vis_range.clone(),
246	                );
247	                order += 1;
248	            }
249	        }
250	    }
251	}
252	
253	// ── functions / callables ──────────────────────────────────────────────────────
254	
255	/// Walk a `function_item`. `assoc=false` → a free fn: a Value(callable) binding
256	/// in `scope`, body Callable parented at `scope`. `assoc=true` → the binding is
257	/// added by the type walker into the type scope; here we only build the BODY,
258	/// re-parented to the ENCLOSING MODULE (`ctx.module`) so it is not bare-visible.
259	pub(in crate::name_resolution::rust_populator::walk) fn walk_function(
260	    b: &mut Builder<'_>,
261	    path: &str,
262	    nid: &NodeId,
263	    scope: ScopeId,
264	    ctx: &Ctx,
265	    assoc: bool,
266	) {
267	    let (name, params_nid, body_nid, vis_kind, cond) = with_node(b, path, nid, |pf, n| {
268	        (
269	            name_text(pf, n).unwrap_or_default(),
270	            n.child_by_field_name("parameters").map(NodeId::of),
271	            n.child_by_field_name("body").map(NodeId::of),
272	            parse_vis(pf, n).0,
273	            parse_cfg_for_item(pf, n),
274	        )
275	    });
276	    if name.is_empty() {
277	        return;
278	    }
279	    let v = vis(vis_kind, None);
280	    if !assoc {
281	        let item = b.fresh_item();
282	        b.add_binding(
283	            scope,
284	            name.clone(),
285	            NS_VALUE,
286	            BindTarget::Resolved(Target::Item {
287	                id: item,
288	                ns: NS_VALUE,
289	                owns: None,
290	                callable: true,
291	            }),
292	            v,
293	            cond.clone(),
294	            vec![full_scope_span(b, scope, ctx.file)],
295	        );
296	    }
297	    // The body Callable scope. For a free fn its lexical parent IS the module
298	    // (`scope == ctx.module` at module level). For an associated fn we FORCE the
299	    // parent to `ctx.module` (NOT the type scope), satisfying the
300	    // not-bare-visible obligation.
301	    let body_parent = if assoc { ctx.module } else { scope };
302	    if let Some(body_nid) = body_nid {
303	        let (blo, bhi) = node_range(&body_nid);
304	        let body_scope = b.add_scope(
305	            ScopeKind::Callable,
306	            Some(body_parent),
307	            ctx.file,
308	            blo,
309	            bhi,
310	            cond.clone(),
311	        );
312	        if let Some(params_nid) = params_nid {
313	            bind_params(b, path, &params_nid, body_scope, ctx.file, bhi);
314	        }
315	        let body_ctx = Ctx {
316	            file: ctx.file,
317	            dir: ctx.dir.clone(),
318	            module: ctx.module,
319	        };
320	        walk_block_body(b, path, &body_nid, body_scope, &body_ctx);
321	    }
322	}
323	
324	/// Bind every parameter pattern as a `Target::Local` in `body_scope`.
325	fn bind_params(
326	    b: &mut Builder<'_>,
327	    path: &str,
328	    params_nid: &NodeId,
329	    body_scope: ScopeId,
330	    file: FileId,
331	    body_end: usize,
332	) {
333	    let facts = with_node(b, path, params_nid, |pf, n| {
334	        let mut out = Vec::new();
335	        let mut cursor = n.walk();
336	        for c in n.children(&mut cursor) {
337	            if c.kind() == "parameter" {
338	                let annotation = c
339	                    .child_by_field_name("type")
340	                    .map(|ty| pf.node_text(&ty).trim().to_string())
341	                    .filter(|s| !s.is_empty());
342	                if let Some(p) = c.child_by_field_name("pattern") {
343	                    let mut names = Vec::new();
344	                    pattern_idents(pf, &p, &mut names);
345	                    for name in names {
346	                        out.push((
347	                            name,
348	                            LocalFact {
349	                                kind: BindingKind::Param,
350	                                annotation: annotation.clone(),
351	                                init: None,
352	                            },
353	                        ));
354	                    }
355	                }
356	            }
357	        }
358	        out
359	    });
360	    for (name, fact) in facts {
361	        add_locals(b, body_scope, file, body_end, &[name], fact);
362	    }
363	}
