1	//! Block / statement / expression descent + local-pattern extraction.
2	//!
3	//! Walks fn/closure bodies, nested blocks, `let`, and the pattern-introducing
4	//! control-flow forms (`for`/`match`/`if let`/`while let`), minting `Block`/
5	//! `Callable` scopes and `Target::Local` bindings. Item-statements inside a
6	//! block delegate back to [`super::items`] via [`super::walk_item`]-style calls.
7	
8	use tree_sitter::Node;
9	
10	use crate::ast::ParsedFile;
11	use crate::name_resolution::binding_lookup::{BindingKind, InitExpr, LocalFact};
12	use crate::name_resolution::rust_policy::{NS_VALUE, VIS_PUB};
13	use crate::name_resolution::types::{
14	    BindTarget, BindingRef, FileId, ScopeId, ScopeKind, SourceLoc, Span, Target,
15	};
16	
17	use super::super::builder::Builder;
18	use super::super::scopes::{pattern_idents, vis};
19	use super::items::{walk_function, walk_mod_item, walk_use};
20	use super::types::{
21	    walk_enum, walk_impl, walk_macro_def, walk_macro_invocation, walk_struct, walk_value_item,
22	};
23	use super::{named_children, node_range, scope_end_byte, with_node, Ctx, NodeId};
24	
25	/// Walk a fn-body `block`: a sequence of statements introducing locals (`let`),
26	/// nested blocks, `use`, macros, control-flow with patterns.
27	pub(in crate::name_resolution::rust_populator::walk) fn walk_block_body(
28	    b: &mut Builder<'_>,
29	    path: &str,
30	    body_nid: &NodeId,
31	    block_scope: ScopeId,
32	    ctx: &Ctx,
33	) {
34	    let stmts = with_node(b, path, body_nid, |_pf, n| named_children(n));
35	    for st in stmts {
36	        walk_stmt(b, path, st, block_scope, ctx);
37	    }
38	}
39	
40	/// Dispatch a statement / expression that may introduce locals or sub-scopes.
41	fn walk_stmt(b: &mut Builder<'_>, path: &str, nid: NodeId, scope: ScopeId, ctx: &Ctx) {
42	    match nid.kind.as_str() {
43	        "let_declaration" => walk_let(b, path, &nid, scope, ctx),
44	        "use_declaration" => walk_use(b, path, &nid, scope, ctx),
45	        "macro_definition" => walk_macro_def(b, path, &nid, scope, ctx),
46	        // Item definitions ARE allowed inside a block (item statements).
47	        "function_item" => walk_function(b, path, &nid, scope, ctx, false),
48	        "struct_item" | "union_item" => walk_struct(b, path, &nid, scope, ctx),
49	        "enum_item" => walk_enum(b, path, &nid, scope, ctx),
50	        "impl_item" => walk_impl(b, path, &nid, scope, ctx),
51	        "const_item" | "static_item" => walk_value_item(b, path, &nid, scope, ctx),
52	        "mod_item" => walk_mod_item(b, path, &nid, scope, ctx),
53	        "expression_statement" | "block" => walk_stmt_or_block(b, path, &nid, scope, ctx),
54	        _ => {
55	            // Other expressions may still contain macro invocations / closures /
56	            // control flow with patterns → descend.
57	            walk_expr(b, path, &nid, scope, ctx);
58	        }
59	    }
60	}
61	
62	fn walk_let(b: &mut Builder<'_>, path: &str, nid: &NodeId, scope: ScopeId, ctx: &Ctx) {
63	    let (names, annotation, init, kind, value_nid) = with_node(b, path, nid, |pf, n| {
64	        let mut names = Vec::new();
65	        let mut simple_pattern = false;
66	        if let Some(p) = n.child_by_field_name("pattern") {
67	            simple_pattern = p.kind() == "identifier";
68	            pattern_idents(pf, &p, &mut names);
69	        }
70	        let annotation = n
71	            .child_by_field_name("type")
72	            .map(|ty| pf.node_text(&ty).trim().to_string())
73	            .filter(|s| !s.is_empty());
74	        let value = n.child_by_field_name("value");
75	        let init = value.and_then(|value| init_expr(pf, &value));
76	        let kind = if simple_pattern {
77	            BindingKind::Let
78	        } else {
79	            BindingKind::Pattern
80	        };
81	        (names, annotation, init, kind, value.map(NodeId::of))
82	    });
83	    let scope_end = scope_end_byte(b, scope, ctx.file);
84	    add_locals(
85	        b,
86	        scope,
87	        ctx.file,
88	        scope_end,
89	        &names,
90	        LocalFact {
91	            kind,
92	            annotation,
93	            init,
94	        },
95	    );
96	    // The initializer expression may contain closures / blocks / macros.
97	    if let Some(value_nid) = value_nid {
98	        walk_expr(b, path, &value_nid, scope, ctx);
99	    }
100	}
101	
102	/// Walk an `expression_statement` or `block` node: a nested `{}` becomes a new
103	/// `Block` scope; otherwise descend into the expression.
104	pub(in crate::name_resolution::rust_populator::walk) fn walk_stmt_or_block(
105	    b: &mut Builder<'_>,
106	    path: &str,
107	    nid: &NodeId,
108	    scope: ScopeId,
109	    ctx: &Ctx,
110	) {
111	    if nid.kind == "block" {
112	        let (lo, hi) = node_range(nid);
113	        let inner = b.add_scope(ScopeKind::Block, Some(scope), ctx.file, lo, hi, None);
114	        walk_block_body(b, path, nid, inner, ctx);
115	    } else {
116	        walk_expr(b, path, nid, scope, ctx);
117	    }
118	}
119	
120	/// Generic expression descent: handle the pattern-introducing control-flow forms
121	/// (`for`/`match`/`if let`/`while let`/closures) + nested blocks + macros, and
122	/// recurse into all other children.
123	fn walk_expr(b: &mut Builder<'_>, path: &str, nid: &NodeId, scope: ScopeId, ctx: &Ctx) {
124	    match nid.kind.as_str() {
125	        "block" => {
126	            walk_stmt_or_block(b, path, nid, scope, ctx);
127	            return;
128	        }
129	        "macro_invocation" => {
130	            walk_macro_invocation(b, path, nid, scope, ctx);
131	            // fall through to descend (args may contain more)
132	        }
133	        "closure_expression" => {
134	            walk_closure(b, path, nid, scope, ctx);
135	            return;
136	        }
137	        "for_expression" => {
138	            walk_for(b, path, nid, scope, ctx);
139	            return;
140	        }
141	        "match_expression" => {
142	            walk_match(b, path, nid, scope, ctx);
143	            return;
144	        }
145	        "if_expression" | "while_expression" => {
146	            walk_if_while(b, path, nid, scope, ctx);
147	            return;
148	        }
149	        _ => {}
150	    }
151	    // Default: recurse into named children within the same scope.
152	    let children = with_node(b, path, nid, |_pf, n| named_children(n));
153	    for child in children {
154	        walk_expr(b, path, &child, scope, ctx);
155	    }
156	}
157	
158	fn walk_closure(b: &mut Builder<'_>, path: &str, nid: &NodeId, scope: ScopeId, ctx: &Ctx) {
159	    let (names, body_nid, lo, hi) = with_node(b, path, nid, |pf, n| {
160	        let mut names = Vec::new();
161	        if let Some(params) = n.child_by_field_name("parameters") {
162	            let mut c = params.walk();
163	            for ch in params.children(&mut c) {
164	                if matches!(ch.kind(), "|" | ",") {
165	                    continue;
166	                }
167	                pattern_idents(pf, &ch, &mut names);
168	            }
169	        }
170	        (
171	            names,
172	            n.child_by_field_name("body").map(NodeId::of),
173	            n.start_byte(),
174	            n.end_byte(),
175	        )
176	    });
177	    // A closure body is a Callable scope; its args are locals there.
178	    let body_scope = b.add_scope(ScopeKind::Callable, Some(scope), ctx.file, lo, hi, None);
179	    add_locals(
180	        b,
181	        body_scope,
182	        ctx.file,
183	        hi,
184	        &names,
185	        LocalFact {
186	            kind: BindingKind::Param,
187	            annotation: None,
188	            init: None,
189	        },
190	    );
191	    if let Some(body_nid) = body_nid {
192	        walk_expr(b, path, &body_nid, body_scope, ctx);
193	    }
194	}
195	
196	fn walk_for(b: &mut Builder<'_>, path: &str, nid: &NodeId, scope: ScopeId, ctx: &Ctx) {
197	    let (names, body_nid, value_nid, lo, hi) = with_node(b, path, nid, |pf, n| {
198	        let mut names = Vec::new();
199	        if let Some(p) = n.child_by_field_name("pattern") {
200	            pattern_idents(pf, &p, &mut names);
201	        }
202	        (
203	            names,
204	            n.child_by_field_name("body").map(NodeId::of),
205	            n.child_by_field_name("value").map(NodeId::of),
206	            n.start_byte(),
207	            n.end_byte(),
208	        )
209	    });
210	    // The loop variable scopes over the loop body block.
211	    let loop_scope = b.add_scope(ScopeKind::Block, Some(scope), ctx.file, lo, hi, None);
212	    add_locals(
213	        b,
214	        loop_scope,
215	        ctx.file,
216	        hi,
217	        &names,
218	        LocalFact {
219	            kind: BindingKind::Pattern,
220	            annotation: None,
221	            init: None,
222	        },
223	    );
224	    if let Some(value_nid) = value_nid {
225	        walk_expr(b, path, &value_nid, scope, ctx); // iterator expr is in outer scope
226	    }
227	    if let Some(body_nid) = body_nid {
228	        walk_block_body(b, path, &body_nid, loop_scope, ctx);
229	    }
230	}
231	
232	fn walk_match(b: &mut Builder<'_>, path: &str, nid: &NodeId, scope: ScopeId, ctx: &Ctx) {
233	    // Each match arm introduces its pattern's bindings over the arm body.
234	    let (value_nid, arms) = with_node(b, path, nid, |_pf, n| {
235	        let value = n.child_by_field_name("value").map(NodeId::of);
236	        let mut arms = Vec::new();
237	        if let Some(body) = n.child_by_field_name("body") {
238	            let mut c = body.walk();
239	            for ch in body.children(&mut c) {
240	                if ch.kind() == "match_arm" {
241	                    arms.push(NodeId::of(ch));
242	                }
243	            }
244	        }
245	        (value, arms)
246	    });
247	    if let Some(value_nid) = value_nid {
248	        walk_expr(b, path, &value_nid, scope, ctx);
249	    }
250	    for arm in arms {
251	        let (names, arm_value, lo, hi) = with_node(b, path, &arm, |pf, n| {
252	            let mut names = Vec::new();
253	            if let Some(p) = n.child_by_field_name("pattern") {
254	                collect_match_pattern(pf, &p, &mut names);
255	            }
256	            (
257	                names,
258	                n.child_by_field_name("value").map(NodeId::of),
259	                n.start_byte(),
260	                n.end_byte(),
261	            )
262	        });
263	        let arm_scope = b.add_scope(ScopeKind::Block, Some(scope), ctx.file, lo, hi, None);
264	        add_locals(
265	            b,
266	            arm_scope,
267	            ctx.file,
268	            hi,
269	            &names,
270	            LocalFact {
271	                kind: BindingKind::Pattern,
272	                annotation: None,
273	                init: None,
274	            },
275	        );
276	        if let Some(arm_value) = arm_value {
277	            walk_expr(b, path, &arm_value, arm_scope, ctx);
278	        }
279	    }
280	}
281	
282	fn walk_if_while(b: &mut Builder<'_>, path: &str, nid: &NodeId, scope: ScopeId, ctx: &Ctx) {
283	    // `if let`/`while let`: the `let_condition`'s pattern bindings scope over the
284	    // consequence/body block. We attach them to a Block scope covering the whole
285	    // if/while node (a safe over-approximation of the let-binding extent).
286	    let (names, blocks, lo, hi) = with_node(b, path, nid, |pf, n| {
287	        let mut names = Vec::new();
288	        let mut blocks = Vec::new();
289	        let mut c = n.walk();
290	        for ch in n.children(&mut c) {
291	            match ch.kind() {
292	                "let_condition" => {
293	                    if let Some(p) = ch.child_by_field_name("pattern") {
294	                        pattern_idents(pf, &p, &mut names);
295	                    }
296	                }
297	                "block" => blocks.push(NodeId::of(ch)),
298	                _ => {}
299	            }
300	        }
301	        (names, blocks, n.start_byte(), n.end_byte())
302	    });
303	    let cond_scope = b.add_scope(ScopeKind::Block, Some(scope), ctx.file, lo, hi, None);
304	    add_locals(
305	        b,
306	        cond_scope,
307	        ctx.file,
308	        hi,
309	        &names,
310	        LocalFact {
311	            kind: BindingKind::Pattern,
312	            annotation: None,
313	            init: None,
314	        },
315	    );
316	    for blk in blocks {
317	        walk_block_body(b, path, &blk, cond_scope, ctx);
318	    }
319	}
320	
321	/// A `match` arm pattern wraps the actual pattern in `match_pattern`.
322	fn collect_match_pattern(pf: &ParsedFile, node: &Node, out: &mut Vec<(String, usize)>) {
323	    if node.kind() == "match_pattern" {
324	        let mut c = node.walk();
325	        for ch in node.children(&mut c) {
326	            if ch.kind() == "if" {
327	                break; // guard expression — not a binding
328	            }
329	            pattern_idents(pf, &ch, out);
330	        }
331	    } else {
332	        pattern_idents(pf, node, out);
333	    }
334	}
335	
336	/// Add a `Target::Local` binding (Value ns) for each `(name, def_byte)`, visible
337	/// from its def byte to `scope_end`.
338	///
339	/// A local's accessibility is its lexical extent, not a Rust `pub`; `VIS_PUB`
340	/// makes the policy's `visible()` return true (the gate is the `vis_extents`).
341	pub(in crate::name_resolution::rust_populator::walk) fn add_locals(
342	    b: &mut Builder<'_>,
343	    scope: ScopeId,
344	    file: FileId,
345	    scope_end: usize,
346	    names: &[(String, usize)],
347	    fact: LocalFact,
348	) {
349	    for (i, (name, def_byte)) in names.iter().enumerate() {
350	        b.add_local_fact(file, *def_byte, fact.clone());
351	        b.add_binding(
352	            scope,
353	            name.clone(),
354	            NS_VALUE,
355	            BindTarget::Resolved(Target::Local(BindingRef {
356	                scope,
357	                ordinal: i as u32,
358	            })),
359	            vis(VIS_PUB, None),
360	            None,
361	            vec![Span {
362	                lo: SourceLoc {
363	                    file,
364	                    byte: *def_byte,
365	                },
366	                hi: SourceLoc {
367	                    file,
368	                    byte: scope_end.max(def_byte + 1),
369	                },
370	            }],
371	        );
372	    }
373	}
374	
375	fn init_expr(pf: &ParsedFile, value: &Node) -> Option<InitExpr> {
376	    match value.kind() {
377	        "call_expression" => {
378	            let function = value
379	                .child_by_field_name("function")
380	                .or_else(|| value.child_by_field_name("name"))?;
381	            let function_text = pf.node_text(&function).trim();
382	            if let Some((_ty, ctor)) = function_text.rsplit_once("::") {
383	                if matches!(ctor, "new" | "default") {
384	                    return Some(InitExpr::Ctor(format!("{function_text}()")));
385	                }
386	            }
387	            Some(InitExpr::Call(format!("{function_text}(...)")))
388	        }
389	        "struct_expression" => {
390	            let ty = value
391	                .child_by_field_name("name")
392	                .or_else(|| value.child_by_field_name("type"))?;
393	            Some(InitExpr::Ctor(format!("{}{{}}", pf.node_text(&ty).trim())))
394	        }
395	        "field_expression" => Some(InitExpr::Field(pf.node_text(value).trim().to_string())),
396	        _ => Some(InitExpr::Other),
397	    }
398	}
399

