+                }
+            }
+            Some(InitExpr::Call(format!("{function_text}(...)")))
+        }
+        "struct_expression" => {
+            let ty = value
+                .child_by_field_name("name")
+                .or_else(|| value.child_by_field_name("type"))?;
+            Some(InitExpr::Ctor(format!("{}{{}}", pf.node_text(&ty).trim())))
+        }
