        let b = local_ref("b").expect("param `b` local binding");
        assert_eq!(a.scope, b.scope, "both params bind in the same callable scope");
        assert_eq!(a.ordinal, 0, "first param ordinal must be 0");
        assert_eq!(b.ordinal, 1, "second param ordinal must be 1 (was 0: ordinal breach)");
