1	//! Direct local-binding lookup for build-time receiver typing.
2	//!
3	//! This intentionally returns the original [`Binding`] rather than the engine's
4	//! [`Candidate`](crate::name_resolution::types::Candidate), because the
5	//! Task-2.3 receiver typer needs the binding span as a def-byte identity.
6	
7	use crate::name_resolution::graph::ScopeGraph;
8	use crate::name_resolution::rust_policy::{EK_GLOB, NS_VALUE};
9	use crate::name_resolution::rust_populator::enclosing_scope;
10	use crate::name_resolution::types::{BindTarget, Binding, FileId, ScopeKind, SourceLoc, Target};
11	use serde::{Deserialize, Serialize};
12	
13	/// Syntactic kind of a Rust local binding.
14	#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
15	pub enum BindingKind {
16	    Param,
17	    Let,
18	    Pattern,
19	}
20	
21	/// Syntactic initializer shape for a Rust local binding.
22	#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
23	pub enum InitExpr {
24	    /// `T::new()` / `T::default()` / `T { ... }`.
25	    Ctor(String),
26	    /// `e.f`.
27	    Field(String),
28	    /// `g(...)`.
29	    Call(String),
30	    Other,
31	}
32	
33	/// Syntactic local-binding fact keyed by `(FileId, def_byte)`.
34	#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
35	pub struct LocalFact {
36	    pub kind: BindingKind,
37	    pub annotation: Option<String>,
38	    pub init: Option<InitExpr>,
39	}
40	
41	/// Return the nearest visible value binding named `name` at `(file, at_byte)`.
42	pub fn lookup_visible_binding<'a>(
43	    graph: &'a ScopeGraph,
44	    file: FileId,
45	    at_byte: usize,
46	    name: &str,
47	) -> Option<&'a Binding> {
48	    let at = SourceLoc {
49	        file,
50	        byte: at_byte,
51	    };
52	    let mut cur = enclosing_scope(graph, file, at_byte);
53	    while let Some(scope_id) = cur {
54	        let mut matches = graph.bindings.iter().filter(|binding| {
55	            binding.scope == scope_id
56	                && binding.name == name
57	                && binding.ns == NS_VALUE
58	                && matches!(&binding.target, BindTarget::Resolved(Target::Local(_)))
59	                && vis_extent_covers(binding, &at)
60	        });
61	        let first = matches.next();
62	        if matches.next().is_some() {
63	            return None;
64	        }
65	        if first.is_some() {
66	            return first;
67	        }
68	        if macro_wildcard_poisons(graph, scope_id, &at) {
69	            return None;
70	        }
71	        let kind = match graph.scope(scope_id) {
72	            Some(scope) => &scope.kind,
73	            None => return None,
74	        };
75	        if !matches!(
76	            kind,
77	            ScopeKind::Block | ScopeKind::Callable | ScopeKind::Type
78	        ) {
79	            break;
80	        }
81	        cur = graph.parent_of(scope_id);
82	    }
83	    None
84	}
85	
86	fn vis_extent_covers(binding: &Binding, at: &SourceLoc) -> bool {
87	    if binding.vis_extents.is_empty() {
88	        return true;
89	    }
90	    binding
91	        .vis_extents
92	        .iter()
93	        .any(|span| span.lo.file == at.file && at.byte >= span.lo.byte && at.byte < span.hi.byte)
94	}
95	
96	fn macro_wildcard_poisons(
97	    graph: &ScopeGraph,
98	    scope: crate::name_resolution::types::ScopeId,
99	    at: &SourceLoc,
100	) -> bool {
101	    graph.macro_wildcards.iter().any(|wildcard| {
102	        wildcard.scope == scope
103	            && wildcard.ns == NS_VALUE
104	            && wildcard.range.lo.file == at.file
105	            && at.byte >= wildcard.range.lo.byte
106	            && at.byte < wildcard.range.hi.byte
107	    }) || graph.edges.iter().any(|edge| {
108	        edge.from == scope
109	            && edge.kind == EK_GLOB
110	            && matches!(&edge.to, BindTarget::Pending(_, _))
111	            && edge.vis_range.as_ref().is_none_or(|span| {
112	                span.lo.file == at.file && at.byte >= span.lo.byte && at.byte < span.hi.byte
113	            })
114	    })
115	}
